package com.readwide.manager.archive;
import org.junit.*;import org.junit.rules.TemporaryFolder;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;import java.lang.reflect.Field;
import static org.junit.Assert.*;
public class AlzEggDecoderRound4Test {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 private void decode(boolean egg,int method,boolean encrypted,int parts)throws Exception{byte[] plain=Round4Fixtures.data(190043);File dir=temp.newFolder();byte[] content=egg?Round4Fixtures.egg(plain,method,encrypted):Round4Fixtures.alz(plain,method,encrypted);File source;
  if(parts>1){List<File> files=egg?Round4Fixtures.splitEgg(dir,"book",content,parts):Round4Fixtures.splitAlz(dir,"book",content,parts);source=files.get(files.size()-1);}else source=Round4Fixtures.write(dir,egg?"book.egg":"book.alz",content);
  File out=temp.newFile();assertTrue(egg?EggArchiveReader.extractSingleEntry(source,"data.bin",out,encrypted?Round4Fixtures.PASSWORD:null):AlzipArchiveReader.extractSingleEntry(source,"data.bin",out,encrypted?Round4Fixtures.PASSWORD:null));assertArrayEquals(plain,Files.readAllBytes(out.toPath()));}
 @Test public void alzStoreSingle()throws Exception{decode(false,0,false,1);}
 @Test public void alzDeflateSingle()throws Exception{decode(false,2,false,1);}
 @Test public void alzDeflateLaterSplitSelection()throws Exception{decode(false,2,false,7);}
 @Test public void alzEncryptedDeflateLaterSelection()throws Exception{decode(false,2,true,5);}
 @Test public void eggStoreSingle()throws Exception{decode(true,0,false,1);}
 @Test public void eggDeflateSingle()throws Exception{decode(true,1,false,1);}
 @Test public void eggDeflateLaterSplitSelection()throws Exception{decode(true,1,false,7);}
 @Test public void eggEncryptedDeflateLaterSelection()throws Exception{decode(true,1,true,5);}
 @Test public void eggAzoStoredBlockLaterSelection()throws Exception{decode(true,3,false,3);}
 @Test public void wrongZipCryptoPasswordsPreserveOldOutput()throws Exception{for(boolean egg:new boolean[]{false,true}){File archive=Round4Fixtures.write(temp.newFolder(),egg?"book.egg":"book.alz",egg?Round4Fixtures.egg(Round4Fixtures.data(50),1,true):Round4Fixtures.alz(Round4Fixtures.data(50),2,true));File out=temp.newFile();Files.write(out.toPath(),new byte[]{19});assertThrows(IOException.class,()->{if(egg)EggArchiveReader.extractSingleEntry(archive,"data.bin",out,"wrong".toCharArray());else AlzipArchiveReader.extractSingleEntry(archive,"data.bin",out,"wrong".toCharArray());});assertArrayEquals(new byte[]{19},Files.readAllBytes(out.toPath()));}}
 @Test public void corruptStorePayloadsPreserveOldOutput()throws Exception{for(boolean egg:new boolean[]{false,true}){byte[] b=egg?Round4Fixtures.egg(Round4Fixtures.data(50),0,false):Round4Fixtures.alz(Round4Fixtures.data(50),0,false);b[b.length-5]^=1;File archive=Round4Fixtures.write(temp.newFolder(),egg?"book.egg":"book.alz",b);File out=temp.newFile();Files.write(out.toPath(),new byte[]{19});assertThrows(IOException.class,()->{if(egg)EggArchiveReader.extractSingleEntry(archive,"data.bin",out,null);else AlzipArchiveReader.extractSingleEntry(archive,"data.bin",out,null);});assertArrayEquals(new byte[]{19},Files.readAllBytes(out.toPath()));}}
 @Test public void repeatedDeflateOpenReadCloseWorks()throws Exception{byte[] raw=Round4Fixtures.data(12347),packed=Round4Fixtures.deflate(raw);for(int i=0;i<50;i++)try(InputStream in=new OwnedDeflateInputStream(new ByteArrayInputStream(packed))){assertArrayEquals(raw,in.readAllBytes());}}
 static Inflater inflater(InflaterInputStream in)throws Exception{Field f=InflaterInputStream.class.getDeclaredField("inf");f.setAccessible(true);return (Inflater)f.get(in);}
 @Test public void deflateReleasesSuppliedInflater()throws Exception{OwnedDeflateInputStream in=new OwnedDeflateInputStream(new ByteArrayInputStream(Round4Fixtures.deflate(new byte[]{1})));Inflater engine=inflater(in);in.close();assertThrows(NullPointerException.class,engine::getBytesRead);in.close();}
 @Test public void deflateReleasesInflaterWhenSourceCloseFails()throws Exception{OwnedDeflateInputStream in=new OwnedDeflateInputStream(new ByteArrayInputStream(new byte[0]){@Override public void close()throws IOException{throw new IOException("close failure");}});Inflater engine=inflater(in);assertThrows(IOException.class,in::close);assertThrows(NullPointerException.class,engine::getBytesRead);in.close();assertThrows(IOException.class,in::read);}
 @Test public void deflateRejectsZeroProgress()throws Exception{try(InputStream in=new OwnedDeflateInputStream(new InputStream(){public int read(){return 0;}public int read(byte[]b,int o,int n){return 0;}})){assertThrows(IOException.class,in::read);}}
 @Test public void deflateHonorsInterruption()throws Exception{try(InputStream in=new OwnedDeflateInputStream(new ByteArrayInputStream(new byte[0]))){Thread.currentThread().interrupt();assertThrows(InterruptedIOException.class,in::read);assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}}
 @Test public void deflateReadsCompressedSourceInLargeChunks()throws Exception{byte[] raw=Round4Fixtures.data(500000);class Counted extends ByteArrayInputStream{int calls;Counted(byte[] b){super(b);}public synchronized int read(byte[] b,int o,int n){calls++;return super.read(b,o,n);}}Counted source=new Counted(Round4Fixtures.deflate(raw));try(InputStream in=new OwnedDeflateInputStream(source)){assertArrayEquals(raw,in.readAllBytes());}assertTrue("bulk-source calls="+source.calls,source.calls<12);}
 static byte[] lzma(long dictionary,int propsSize,int props){byte[] b=new byte[9];b[2]=(byte)propsSize;b[4]=(byte)props;for(int i=0;i<4;i++)b[5+i]=(byte)(dictionary >>>(8*i));return b;}
 @Test public void lzmaUnsignedDictionaryClampsToIndependentBlock()throws Exception{assertEquals(65536,EggLzmaProperties.parse(lzma(0xffffffffL,5,93),65536,Integer.MAX_VALUE-15).dictionarySize);}
 @Test public void lzmaSmallDictionaryPreservesItsLimit()throws Exception{assertEquals(8192,EggLzmaProperties.parse(lzma(8192,5,93),100000,Integer.MAX_VALUE-15).dictionarySize);}
 @Test public void lzmaMinimumDictionaryAndEmptyBlock()throws Exception{assertEquals(4096,EggLzmaProperties.parse(lzma(0,0,93),0,Integer.MAX_VALUE-15).dictionarySize);}
 @Test public void lzmaInvalidPropertiesRejected()throws Exception{assertThrows(IOException.class,()->EggLzmaProperties.parse(lzma(8192,4,93),10000,Integer.MAX_VALUE-15));assertThrows(IOException.class,()->EggLzmaProperties.parse(lzma(8192,5,225),10000,Integer.MAX_VALUE-15));assertThrows(IOException.class,()->EggLzmaProperties.parse(new byte[8],10000,Integer.MAX_VALUE-15));assertThrows(IOException.class,()->EggLzmaProperties.parse(lzma(8192,5,93),-1,Integer.MAX_VALUE-15));}
 @Test public void lzmaUnrepresentableIndependentHistoryRejected()throws Exception{assertThrows(ArchiveSupport.UnsupportedArchiveFeatureException.class,()->EggLzmaProperties.parse(lzma(0xffffffffL,5,93),0xffffffffL,Integer.MAX_VALUE-15));}

 @Test public void alzTrimmedBzipFixtureSurvivesSplitBoundaryChanges()throws Exception{byte[] plain="ALZ bzip2 single block payload. ".repeat(40).getBytes(java.nio.charset.StandardCharsets.US_ASCII);byte[] packed=Base64.getDecoder().decode(Round4Fixtures.ALZ_BZ_SINGLE_BLOCK_B64);List<File>f=Round4Fixtures.splitAlz(temp.newFolder(),"book",Round4Fixtures.alzStored(plain,1,packed,false),3);File out=temp.newFile();assertTrue(AlzipArchiveReader.extractSingleEntry(f.get(2),"data.bin",out,null));assertArrayEquals(plain,Files.readAllBytes(out.toPath()));}
 private void aesFixture(String fixture,String text)throws Exception{List<File> f=Round4Fixtures.splitEgg(temp.newFolder(),"book",Base64.getDecoder().decode(fixture),3);File out=temp.newFile();assertTrue(EggArchiveReader.extractSingleEntry(f.get(2),"secret.txt",out,"pw1717".toCharArray()));assertArrayEquals(text.repeat(10).getBytes(java.nio.charset.StandardCharsets.US_ASCII),Files.readAllBytes(out.toPath()));assertThrows(IOException.class,()->EggArchiveReader.extractSingleEntry(f.get(1),"secret.txt",out,"wrong".toCharArray()));assertArrayEquals(text.repeat(10).getBytes(java.nio.charset.StandardCharsets.US_ASCII),Files.readAllBytes(out.toPath()));}
 @Test public void eggExistingAes128StoreFixtureReadsFromLaterPart()throws Exception{aesFixture(Round4Fixtures.AES128_STORE_B64,"aes secret payload ");}
 @Test public void eggExistingAes256StoreFixtureReadsFromLaterPart()throws Exception{aesFixture(Round4Fixtures.AES256_STORE_B64,"aes secret payload ");}
 @Test public void eggExistingAes256DeflateFixtureReadsFromLaterPart()throws Exception{aesFixture(Round4Fixtures.AES256_DEFLATE_B64,"aes secret deflate payload ");}
}
